def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_divisors(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

solutions = []
for k in range(1, 101):
    N = 2 * (k**3)
    d_N = count_divisors(N)
    target = 2 * k
    if d_N == target:
        solutions.append(k)

print(f"Solutions found up to k=100: {solutions}")
